function StatCard({ label, value, accent }: { label: string; value: string; accent?: boolean }) {
  return (
    <Card className="border-border/30 bg-muted/15">
      <CardHeader className="pb-2 pt-5">
        <CardTitle className="text-xs font-medium text-muted-foreground uppercase tracking-wider">{label}</CardTitle>
      </CardHeader>
      <CardContent>
        <p className={`font-display text-2xl font-bold tracking-tight ${accent ? "text-success" : "text-foreground"}`}>{value}</p>
      </CardContent>
    </Card>
  );
}

function EditProfileDialog({
  user,
  profile,
  open,
  onOpenChange,
}: {
  user: any;
  profile: any;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const queryClient = useQueryClient();
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (profile) {
      setName(profile.name ?? "");
      setPhone(profile.phone ?? "");
    } else if (user) {
      setName(user.user_metadata?.name ?? "");
      setPhone(user.user_metadata?.phone ?? "");
    }
  }, [profile, user]);

  async function handleSave(e: React.FormEvent) {
    e.preventDefault();
    if (!name.trim()) return toast.error("Por favor, informe seu nome.");
    setSaving(true);

    const cleanPhone = phone.trim();

    const { error } = await supabase.from("profiles").upsert({
      id: user.id,
      name: name.trim(),
      email: user.email,
      phone: cleanPhone || null,
    });

    if (error) {
      setSaving(false);
      return toast.error("NÃ£o foi possÃ­vel salvar o perfil.");
    }

    if (cleanPhone) {
      try {
        await supabase.rpc("migrate_reservations_by_phone", {
          p_new_user_id: user.id,
          p_phone: cleanPhone,
        });
      } catch (err) {
        console.warn("Aviso ao migrar reservas:", err);
      }
    }

    setSaving(false);
    queryClient.invalidateQueries();
    toast.success("Perfil atualizado com sucesso!");
    onOpenChange(false);
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md panel border-border/60">
        <DialogHeader>
          <DialogTitle className="text-xl">Editar Perfil Pessoal</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSave} className="space-y-4 pt-2">
          <div className="space-y-2">
            <Label htmlFor="prof-email">E-mail</Label>
            <Input id="prof-email" value={user?.email || ""} disabled className="bg-muted/50 font-mono text-sm" />
            <p className="text-xs text-muted-foreground">O e-mail da sua conta nÃ£o pode ser alterado.</p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="prof-name">Nome completo</Label>
            <Input
              id="prof-name"
              required
              maxLength={80}
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="prof-phone">WhatsApp</Label>
            <PhoneInput id="prof-phone" value={phone} onChange={setPhone} />
          </div>

          <div className="flex justify-end gap-2 pt-2">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button type="submit" disabled={saving}>
              {saving && <Loader2 className="size-4 animate-spin" />} Salvar Perfil
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

function SyncPhoneModal({
  user,
  profile,
  open,
  onOpenChange,
}: {
  user: any;
  profile: any;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const queryClient = useQueryClient();
  const [phone, setPhone] = useState("");
  const [saving, setSaving] = useState(false);

  async function handleSync(e: React.FormEvent) {
    e.preventDefault();
    const cleanPhone = phone.trim();
    if (!cleanPhone || cleanPhone.replace(/\D/g, "").length < 8) {
      return toast.error("Por favor, informe um nÃºmero de WhatsApp com DDD vÃ¡lido.");
    }

    setSaving(true);
    try {
      // Salva telefone no perfil do cliente
      const customerName = profile?.name || user?.user_metadata?.name || user?.user_metadata?.full_name || "Cliente";
      const { error: profError } = await supabase.from("profiles").upsert({
        id: user.id,
        name: customerName,
        email: user.email,
        phone: cleanPhone,
      });

      if (profError) throw profError;

      // Migrar reservas GUEST associadas a este WhatsApp
      try {
        await supabase.rpc("migrate_reservations_by_phone", {
          p_new_user_id: user.id,
          p_phone: cleanPhone,
        });
      } catch (err) {
        console.warn("Aviso ao rodar RPC de sincronizaÃ§Ã£o:", err);
      }

      // Atualiza os dados na tela em tempo real
      await queryClient.invalidateQueries();
      toast.success("WhatsApp salvo com sucesso! Suas reservas foram sincronizadas.");
      onOpenChange(false);
    } catch (err: any) {
      toast.error(`Erro ao salvar: ${err?.message || "Tente novamente"}`);
    } finally {
      setSaving(false);
    }
  }

  const handleDismiss = () => {
    if (typeof window !== "undefined") {
      sessionStorage.setItem("dismissed_phone_prompt", "true");
    }
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md panel border-border/60">
        <DialogHeader>
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-primary/10 text-primary">
              <Sparkles className="size-6 text-primary" />
            </div>
            <div>
              <DialogTitle className="text-xl font-bold">Vincular Reservas com WhatsApp</DialogTitle>
              <DialogDescription className="text-xs text-muted-foreground mt-0.5">
                Conecte seu WhatsApp para sincronizar automaticamente pedidos e reservas feitas com lojistas.
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <form onSubmit={handleSync} className="space-y-4 pt-2">
          <div className="p-3 rounded-lg bg-muted/40 border border-border/40 text-xs text-muted-foreground leading-relaxed">
            Identificamos que vocÃª fez login com a sua conta Google. Para encontrarmos suas reservas de miniaturas feitas diretamente com os lojistas e adicionÃ¡-las ao seu painel e garagem, informe o nÃºmero de WhatsApp usado nos seus pedidos.
          </div>

          <div className="space-y-2">
            <Label htmlFor="sync-phone" className="text-xs font-semibold">
              Seu WhatsApp com DDD
            </Label>
            <PhoneInput id="sync-phone" value={phone} onChange={setPhone} required />
          </div>

          <div className="flex items-center justify-between pt-2">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleDismiss}
              disabled={saving}
              className="text-xs text-muted-foreground hover:text-foreground"
            >
              Lembrar mais tarde
            </Button>
            <Button type="submit" size="sm" disabled={saving} className="gap-2">
              {saving ? (
                <>
                  <Loader2 className="size-4 animate-spin" /> Sincronizando...
                </>
              ) : (
                <>
                  <CheckCircle2 className="size-4" /> Salvar e Sincronizar
                </>
              )}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}
